const body = $('Expense webhook').first().json.body;
const today = $now.setZone('Asia/Seoul').toFormat('yyyy-MM-dd');
const isDate = s => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s) && !isNaN(Date.parse(s + 'T00:00:00Z')) && new Date(s + 'T00:00:00Z').toISOString().slice(0, 10) === s;
const dayKo = s => '일월화수목금토'[new Date(s + 'T00:00:00Z').getUTCDay()];
const addDays = (s, n) => new Date(Date.parse(s + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
const daysBetween = (a, b) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
// LLM이 날짜를 지어내지 않았는지: 요청 문장에 날짜를 말하는 표현이 있어야 날짜를 믿는다
const mentionsDate = text => /\d{1,2}\s*월|\d{1,2}\s*일|\d{4}-\d{1,2}-\d{1,2}|\d{1,2}\/\d{1,2}|오늘|내일|모레|글피|요일|이번\s*주|다음\s*주|주말|월말|월초/.test(String(text ?? ''));
const range = (a, b) => (!b || a === b) ? `${a}(${dayKo(a)})` : `${a}(${dayKo(a)}) ~ ${b}(${dayKo(b)})`;
const won = n => Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',') + '원';
const hash = s => { let h = 5381; for (const c of s) h = ((h * 33) ^ c.codePointAt(0)) >>> 0; return h.toString(36).toUpperCase().slice(-4).padStart(4, '0'); };
const TIER = { '서울': 120000, '부산': 100000, '대구': 100000, '광주': 100000, '대전': 100000, '인천': 100000, '울산': 100000 };
const city = String(body.city ?? '').trim().replace(/(특별시|광역시|시)$/, '');
const user = String(body.user).trim();
const start = String(body.start ?? '').trim();
const end = String(body.end ?? '').trim() || start;
const transport = Math.max(0, Math.round(Number(body.transport) || 0));
const out = (route, answer, extra = {}) => [{ json: { route, answer, user, city, ...extra } }];
if (!city) return out('입력 필요', '출장 가는 도시를 알려 주세요. 예: "부산 출장"');
if (!isDate(start) || !isDate(end)) return out('입력 필요', '출장 날짜(가는 날·오는 날)를 알려 주세요. 예: "11월 12일부터 14일까지"');
if (end < start) return out('입력 필요', `오는 날(${end})이 가는 날(${start})보다 빠릅니다.`);
if (start < today) return out('거절', `지난 출장은 출장비 신청이 아니라 정산으로 처리해요. 복귀 후 5일 안에 영수증을 제출해 주세요 (TR-5).`);
// 금액은 LLM이 아니라 규정표로 계산 (TR-1, TR-2, TR-3)
const perNight = TIER[city] ?? 80000;
const nights = daysBetween(start, end);
const days = nights + 1;
const lodging = perNight * nights;
const perDiem = 30000 * days;
const amount = lodging + perDiem + transport;
const breakdown = { lodging: { per_night: perNight, nights, total: lodging }, per_diem: { per_day: 30000, days, total: perDiem }, transport };
const detail = `숙박 ${won(perNight)} × ${nights}박 + 일비 ${won(30000)} × ${days}일 + 교통비 ${won(transport)}${transport ? '' : '(영수증으로 나중에 정산, TR-3)'}`;
const head = `${city} 출장 ${range(start, end)}, ${nights}박 ${days}일`;
if (nights > 7 || amount > 1000000) return out('담당자 연결', `${head} 예상 출장비는 ${won(amount)}입니다. ${nights > 7 ? '7박을 넘는 장기 출장' : '총액 100만 원 초과'}이라 팀장 결재가 필요해 담당자에게 연결했어요 (TR-4). ${detail}`, { amount, breakdown });
const request_id = `T-${start.replace(/-/g, '')}-${hash(user + city + end + transport)}`;
return out('접수 완료', `${head} 출장비 ${won(amount)} 신청을 접수했습니다 (접수 번호 ${request_id}). ${detail}. 복귀 후 5일 안에 영수증을 내 주세요 (TR-5).`,
  { request_id, start, end, nights, days, amount, breakdown });
